<script setup>
import { ref, computed } from 'vue'
import { createCollection } from '../../services/collectionService'
import { LIMITS } from '../../config/constants'
import BaseModal from '../base/BaseModal.vue'
const props=defineProps({open:Boolean}), emit=defineEmits(['close','created'])
const form=ref({title:'',description:'',isPublic:false}), errors=ref({}), submitting=ref(false), apiError=ref('')
const dialogOpen=computed({get:()=>props.open,set:v=>{if(!v)emit('close')}})
function validate(){errors.value={};const title=form.value.title.trim();if(title.length<LIMITS.COLLECTION_TITLE_MIN||title.length>LIMITS.COLLECTION_TITLE_MAX)errors.value.title=`Use de ${LIMITS.COLLECTION_TITLE_MIN} a ${LIMITS.COLLECTION_TITLE_MAX} caracteres.`;if(form.value.description.length>LIMITS.COLLECTION_DESCRIPTION_MAX)errors.value.description=`Máximo ${LIMITS.COLLECTION_DESCRIPTION_MAX} caracteres.`;return !Object.keys(errors.value).length}
async function submit(){apiError.value='';if(!validate())return;submitting.value=true;try{const r=await createCollection({...form.value,title:form.value.title.trim(),description:form.value.description.trim()});emit('created',r.data)}catch(e){apiError.value=e.message||'Não foi possível criar a coleção.'}finally{submitting.value=false}}
</script>
<template><BaseModal v-model="dialogOpen" title="Criar coleção" :busy="submitting" confirm-label="Criar cole&#231;&#227;o" @confirm="submit"><form id="collection-form" novalidate @submit.prevent="submit"><label class="form-label" for="collection-title">Título</label><input id="collection-title" v-model="form.title" class="form-control" :class="{'is-invalid':errors.title}" maxlength="100"/><div v-if="errors.title" class="invalid-feedback d-block">{{errors.title}}</div><label class="form-label mt-3" for="collection-description">Descrição</label><textarea id="collection-description" v-model="form.description" class="form-control" rows="3" maxlength="500"/><div v-if="errors.description" class="text-danger small">{{errors.description}}</div><label class="form-check mt-3"><input v-model="form.isPublic" class="form-check-input" type="checkbox"/><span class="form-check-label">Pública</span></label><div v-if="apiError" class="alert alert-danger mt-3">{{apiError}}</div></form><template #footer><button type="button" class="btn btn-outline-secondary" :disabled="submitting" @click="emit('close')">Cancelar</button><button type="submit" form="collection-form" class="btn btn-primary" :disabled="submitting">{{submitting?'Salvando...':'Criar cole&#231;&#227;o'}}</button></template></BaseModal></template>
